```java
@Override
public void afterCheckRootProject(@NonNull Context context) {
    for (ArrayInfo info : mArrays.values()) {
        if (info.variants.isEmpty()) continue;
        // find default
        Variant defaultVariant = null;
        for (Variant v : info.variants) {
            if (v.config.isEmpty()) {
                defaultVariant = v;
                break;
            }
        }
        if (defaultVariant != null) {
            for (Variant v : info.variants) {
                if (v == defaultVariant) continue;
                if (v.size != defaultVariant.size) {
                    context.report(ISSUE, v.handle.resolve(),
                        String.format("Array \"%1$s\" has %2$d items in %3$s, expected %4$d (size in default configuration)",
                            info.name, v.size, v.config.isEmpty() ? "default" : v.config, defaultVariant.size));
                }
            }
        } else {
            // No default; compare to first variant
            Variant reference = info.variants.get(0);
            for (int i = 1; i < info.variants.size(); i++) {
                Variant v = info.variants.get(i);
                if (v.size != reference.size) {
                    context.report(ISSUE, v.handle.resolve(),
                        String.format("Array \"%1$s\" has %2$d items in %3$s, expected %4$d (size in %5$s)",
                            info.name, v.size, v.config.isEmpty() ? "default" : v.config, reference.size, reference.config.isEmpty() ? "default" : reference.config));
                }
            }
        }
    }
    mArrays.clear();
}
```

