public class ArraySizeDetector extends ResourceXmlDetector {
    private static final String TAG_STRING_ARRAY = "string-array";
    private static final String TAG_INTEGER_ARRAY = "integer-array";
    private static final String TAG_ARRAY = "array";
    private Map<String, List<ArrayInfo>> mArrays;

    private static class ArrayInfo {
        public final String name;
        public final int size;
        public final FolderConfiguration folderConfig;
        public final Location.Handle handle;

        public ArrayInfo(String name, int size, FolderConfiguration folderConfig, Location.Handle handle) {
            this.name = name;
            this.size = size;
            this.folderConfig = folderConfig;
            this.handle = handle;
        }
    }

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_ARRAY, TAG_STRING_ARRAY, TAG_INTEGER_ARRAY);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String name = element.getAttribute(ATTR_NAME);
        if (name == null || name.isEmpty()) return;

        int size = countItems(element);
        Location.Handle handle = context.createLocationHandle(element);
        FolderConfiguration config = context.getFolderConfiguration();
        String key = name;
        if (mArrays == null) mArrays = new HashMap<>();
        List<ArrayInfo> list = mArrays.get(key);
        if (list == null) {
            list = new ArrayList<>();
            mArrays.put(key, list);
        }
        list.add(new ArrayInfo(name, size, config, handle));
    }

    private static int countItems(Element array) { ... }

    @Override
    public void afterCheckProject(Context context) {
        if (mArrays == null) return;
        for (List<ArrayInfo> list : mArrays.values()) {
            ArrayInfo default = null;
            for (ArrayInfo info : list) {
                if (info.folderConfig == null || info.folderConfig.getLocaleQualifier() == null) {
                    default = info;
                    break;
                }
            }
            if (default == null) {
                default = list.get(0); // maybe compare all to first
            }
            for (ArrayInfo info : list) {
                if (info == default) continue;
                if (info.size != default.size) {
                    String msg = String.format("Array \"%1$s\" has %2$d items in %3$s but %4$d in %5$s",
                            info.name, info.size, getFolderName(info), default.size, getFolderName(default));
                    context.report(ISSUE, info.handle.resolve(), msg);
                }
            }
        }
    }

    private static String getFolderName(ArrayInfo info) {
        if (info.folderConfig == null) return "values";
        String s = info.folderConfig.getFolderName(ResourceFolderType.VALUES);
        return s.isEmpty() ? "values" : s;
    }
}
