@Override
public void afterCheckRootProject(@NonNull Context context) {
    Project project = context.getProject();
    XmlParser parser = context.getDriver().getXmlParser();
    if (parser == null) return;
    Map<String, List<ArrayInfo>> map = new HashMap<>();
    for (File file : project.getResourceFiles()) {
        if (!file.getPath().contains("/values") && !file.getPath().contains("\\values")) continue;
        if (!file.isFile() || !file.getName().endsWith(DOT_XML)) continue;
        ResourceFolderType type = ResourceFolderType.getFolderType(file.getParentFile().getName());
        if (type != ResourceFolderType.VALUES) continue;
        Document doc;
        try {
            doc = parser.parseXml(file, project);
        } catch (Exception e) {
            continue;
        }
        if (doc == null) continue;
        String folder = file.getParentFile().getName();
        NodeList roots = doc.getElementsByTagName("resources");
        for (int i=0;i<roots.getLength();i++) {
            Element resources = (Element) roots.item(i);
            NodeList children = resources.getChildNodes();
            for (int j=0;j<children.getLength();j++) {
                Node node = children.item(j);
                if (node.getNodeType() != Node.ELEMENT_NODE) continue;
                Element element = (Element) node;
                String tag = element.getTagName();
                if (!TAG_ARRAY.equals(tag) && !TAG_STRING_ARRAY.equals(tag) && !TAG_INTEGER_ARRAY.equals(tag)) continue;
                String name = element.getAttribute(ATTR_NAME);
                if (name == null || name.isEmpty()) continue;
                int size = countItems(element);
                Location location = parser.getNodeStartLocation(element);
                String key = tag + "/" + name;
                List<ArrayInfo> list = map.get(key);
                if (list == null) {
                    list = new ArrayList<>();
                    map.put(key, list);
                }
                list.add(new ArrayInfo(name, size, folder, Location.create(file, location.getStart(), location.getEnd())));
            }
        }
    }
    // Now compare
    for (List<ArrayInfo> list : map.values()) {
        if (list.size() < 2) continue;
        ArrayInfo reference = null;
        for (ArrayInfo info : list) {
            if (FOLDER_VALUES.equals(info.folder)) {
                reference = info;
                break;
            }
        }
        if (reference == null) {
            reference = list.get(0);
        }
        for (ArrayInfo info : list) {
            if (info == reference) continue;
            if (info.size != reference.size) {
                String message = String.format(
                    "Array \"%1$s\" has %2$d items in %3$s but %4$d in %5$s",
                    info.name, info.size, info.folder, reference.size, reference.folder);
                context.report(ISSUE, info.location, message);
            }
        }
    }
}
```

